function load() {
  try {
    const d = defaultState(); const p = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
    if (!p || typeof p !== 'object') return d;
    const arr = (v, fb) => Array.isArray(v) ? v : fb, obj = (v, fb) => (v && typeof v === 'object') ? Object.assign(fb, v) : fb;
    const s = Object.assign(d, p, { notebook: arr(p.notebook, []), a1: obj(p.a1, d.a1), a2: obj(p.a2, d.a2), a3: obj(p.a3, d.a3), summary: obj(p.summary, d.summary) });
    s.a2.draws = arr(s.a2.draws, []); s.a3.tricks = arr(s.a3.tricks, []);
    if (!Array.isArray(s.a1.axis) || s.a1.axis.length !== 2 || s.a1.axis.some(x => !Number.isFinite(+x))) s.a1.axis = [0, 100];
    if (!SCREENS.includes(s.screen)) s.screen = 'start';
    return s;
  } catch (e) { return defaultState(); }
}

